const input = $input.first().json;
const query = input.query || {};

const nom = (query.name || '').trim();
const aliyahBrut = (query.aliyah ?? '').toString().trim();
const langue = (query.target_language || 'fr').trim();
const avecTraductions = query.include_translations !== 'false';
// Commentaires : ces deux paramètres décident du POIDS de la réponse, pas d'un
// détail d'affichage. Sur Bereshit aliyah 1, l'API rend 3,85 Mo sans filtre
// (2 498 commentaires, 57 commentateurs) contre 80 Ko avec ?commentators=Rashi,
// et 23 Ko avec include_commentaries=false. Ne pas les relayer imposait le
// payload plein au plugin, quoi qu'il demande (azy.daily#198).
const avecCommentaires = query.include_commentaries === 'true';
const commentateurs = (query.commentators || '').trim();

if (!nom) {
  return [{ json: { valide: false, erreur: {
    code: 400,
    message: 'Le paramètre "name" est requis (nom EN canonique, ex. Bereshit)',
    status: 'BAD_REQUEST'
  } } }];
}

// L'aliyah est validée ICI, avant l'appel : l'API renvoie sinon un 422 dont le
// `detail` est un TABLEAU d'objets Pydantic, illisible pour un utilisateur final.
// Une borne connue et fixe (7 aliyot, toujours) mérite un message direct.
let aliyah = null;
if (aliyahBrut !== '') {
  const n = Number(aliyahBrut);
  if (!Number.isInteger(n) || n < 1 || n > 7) {
    return [{ json: { valide: false, erreur: {
      code: 400,
      message: `Aliyah invalide : "${aliyahBrut}". Une parasha compte 7 aliyot, numérotées de 1 à 7. Omettre le paramètre renvoie la parasha entière.`,
      status: 'INVALID_ALIYAH'
    } } }];
  }
  aliyah = n;
}

const params = [];
if (langue) params.push('target_language=' + encodeURIComponent(langue));
if (!avecTraductions) params.push('include_translations=false');
// Explicite dans les DEUX sens : le défaut de l'API est `true`, donc ne rien
// transmettre revient à demander les 2 498 commentaires — 3,85 Mo. Le cas le plus
// courant (un appel sans paramètre) serait aussi le plus coûteux, et l'appelant
// devrait savoir demander moins pour ne pas tout recevoir.
params.push('include_commentaries=' + (avecCommentaires ? 'true' : 'false'));
// La liste passe telle quelle : c'est l'API qui connaît les noms valides, et
// dupliquer la validation ici créerait une seconde source de vérité.
if (commentateurs) params.push('commentators=' + encodeURIComponent(commentateurs));
const requete = params.length ? '?' + params.join('&') : '';

// Une aliyah précise, ou la parasha entière.
const chemin = aliyah
  ? `/api/torah/parashiyot/${encodeURIComponent(nom)}/aliyot/${aliyah}/segments`
  : `/api/torah/parashiyot/${encodeURIComponent(nom)}/segments`;

return [{
  json: {
    valide: true,
    nom: nom,
    aliyah: aliyah,
    target_language: langue,
    include_translations: avecTraductions,
    include_commentaries: avecCommentaires,
    commentators: commentateurs || null,
    chemin: chemin + requete
  }
}];

// --- Désencapsulation de l'erreur HTTP -------------------------------------
// Avec onError: continueRegularOutput, un HTTP Request en échec ne produit PAS
// {statusCode, body} mais l'objet d'erreur axios : statusCode est absent, et le
// statut réel est enfoui dans le message sous la forme « 404 - {"detail":…} ».
// Même parade que Normalize Error de DOC - Render PDF (cf. #422).
function lireErreur(item) {
  let brut = '';
  for (const c of [item?.error?.message, item?.message, item?.error?.description,
                   typeof item?.error === 'string' ? item.error : null]) {
    if (c) { brut = String(c); break; }
  }
  const m = brut.match(/^\s*(\d{3})\s*-\s*/);
  const statut = m ? parseInt(m[1], 10) : null;

  let detail = null;
  const i = brut.indexOf('{'), j = brut.lastIndexOf('}');
  if (i >= 0 && j > i) {
    const bloc = brut.slice(i, j + 1);
    for (const essai of [bloc, bloc.replace(/\\"/g, '"').replace(/\\\\/g, '\\')]) {
      try {
        const o = JSON.parse(essai);
        // Un 422 de FastAPI porte un detail TABLEAU d'objets Pydantic ; les 400 et
        // 404 de l'API portent une chaîne. Sans ce tri, on rendrait « [object Object] ».
        if (Array.isArray(o.detail)) {
          detail = o.detail.map(x => x?.msg || JSON.stringify(x)).join(' ; ');
        } else {
          detail = o.detail || o?.error?.message || o.message || null;
        }
        break;
      } catch (e) { /* essai suivant */ }
    }
  }
  return { statut, detail, brut };
}

const input = $input.first().json;
const p = $('Lire Paramètres').first().json;

const estErreur = input?.error !== undefined || input?.statusCode === undefined;

if (estErreur) {
  const e = lireErreur(input);
  const code = e.statut || 502;

  if (code === 404) {
    return [{ json: {
      success: false,
      name: p.nom,
      aliyah: p.aliyah,
      error: {
        code: 404,
        message: `Parasha introuvable : "${p.nom}". Le nom attendu est le nom EN canonique, sensible à la casse. La liste complète est disponible sur torah-tanakh-parashiot-list.`,
        status: 'PARASHA_NOT_FOUND'
      }
    } }];
  }
  return [{ json: {
    success: false,
    name: p.nom,
    aliyah: p.aliyah,
    error: { code: code, message: e.detail || e.brut || "L'API n'a pas répondu", status: 'API_ERROR' }
  } }];
}

const data = input.body || input;
const segments = data.segments || [];

return [{
  json: {
    success: true,
    name: data.parasha || p.nom,
    aliyah: p.aliyah,
    target_language: p.target_language,
    start_ref: data.start_ref,
    end_ref: data.end_ref,
    segments_count: data.segments_count ?? segments.length,
    translated_count: data.translated_count ?? 0,
    // présent uniquement en mode parasha entière — permet de découper côté client
    aliyot_boundaries: data.aliyot_boundaries || null,
    segments: segments
  }
}];
